def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n <= 2:
        return 'C'

    last_me, last_opp = history[-1]

    opp_d = 0
    my_d = 0
    recent_opp_d = 0
    start = n - 10
    if start < 0:
        start = 0
    for i in range(n):
        me, opp = history[i]
        if opp == 'D':
            opp_d += 1
            if i >= start:
                recent_opp_d += 1
        if me == 'D':
            my_d += 1

    if n >= 8 and (recent_opp_d >= 7 or (recent_opp_d >= 4 and opp_d * 5 >= n * 3)):
        return 'D'

    if last_opp == 'D':
        if last_me == 'D':
            if recent_opp_d >= 6 or opp_d * 4 >= n * 3 or opp_d - my_d >= 6:
                return 'D'
            return 'C'

        if n >= 2 and history[-2][0] == 'D' and history[-2][1] == 'C':
            return 'C'

        if opp_d <= 2 and recent_opp_d <= 2 and rng.random() < 0.7:
            return 'C'

        return 'D'

    if last_opp == 'C':
        if n >= 10 and 3 <= opp_d <= 6 and recent_opp_d <= 3 and rng.random() < 0.3:
            return 'D'

        if last_me == 'D':
            if opp_d == 0:
                if n >= 97 or rng.random() < 0.03:
                    return 'D'
                return 'C'
            if opp_d <= 5 and recent_opp_d <= 4 and rng.random() < 0.1:
                return 'D'
            return 'C'

        if n >= 95 and opp_d <= 1 and rng.random() < 0.2:
            return 'D'

    return 'C'
